<?php
// Unit calendar overlay. A missing month continues to use the legacy calendar.
function lt_work_calendar($pdo,$unit,$month){if(!$unit)return null;try{$s=$pdo->prepare('SELECT * FROM compensation_unit_calendars WHERE facility_code=? AND month_start=?');$s->execute([$unit,$month]);return $s->fetch(PDO::FETCH_ASSOC)?:null;}catch(PDOException $e){if($e->getCode()==='42S02')return null;throw $e;}}
function lt_certificate_gate($pdo,$unit,$fy,$month,$checked){$cal=wd_month_summary($pdo,$fy,$month,$unit);if(!$cal['verified'])return 'ต้องตรวจและยืนยันปฏิทินของเดือนนี้ก่อน';$end=(new DateTimeImmutable($month))->modify('last day of this month')->format('Y-m-d');$s=$pdo->prepare("SELECT COUNT(*) FROM compensation_personnel_leaves l JOIN compensation_personnel p ON p.id=l.personnel_id JOIN compensation_leave_types t ON t.id=l.leave_type_id WHERE p.facility_code=? AND l.date_from<=? AND l.date_to>=? AND (l.status='pending' OR (l.status='approved' AND t.code IN('OFFICIAL','OTHER')))");$s->execute([$unit,$end,$month]);if($s->fetchColumn())return 'ยังมีใบลารอตรวจผล หรือไปราชการ/หยุดอื่นที่ต้องตรวจวันปฏิบัติงานเอง จึงยังไม่ออกใบรับรองอัตโนมัติ';if(!$checked)return 'กรุณาตรวจว่าทะเบียนลาเดือนนี้ครบและยืนยันก่อนเปิดแบบพิมพ์';return '';}
function wd_month_summary($pdo,$fy,$monthStart,$unit=null){$c=lt_work_calendar($pdo,$unit,$monthStart);if(!$c)return wd_legacy_month_summary($pdo,$fy,$monthStart);$o=json_decode($c['overrides_json'],true);$r=['total_days'=>0,'holiday_days'=>0,'work_days'=>0,'weekend_holidays'=>0,'extra_holidays'=>0,'verified'=>(int)$c['verified']];$d=new DateTimeImmutable($monthStart);while($d->format('Y-m')===substr($monthStart,0,7)){$key=$d->format('Y-m-d');$weekend=(int)$d->format('N')>=6;$holiday=isset($o[$key])?(bool)$o[$key]['is_holiday']:$weekend;$r['total_days']++;$r[$holiday?'holiday_days':'work_days']++;if($holiday)$r[$weekend?'weekend_holidays':'extra_holidays']++;$d=$d->modify('+1 day');}return $r;}
function wd_leave_days($pdo,$leave){$unit=$leave['facility_code']??null;if(!$unit&&isset($leave['personnel_id'])){$s=$pdo->prepare('SELECT facility_code FROM compensation_personnel WHERE id=?');$s->execute([$leave['personnel_id']]);$unit=$s->fetchColumn();}if(!$unit)return wd_legacy_leave_days($pdo,$leave);$days=0;$d=new DateTimeImmutable($leave['date_from']);$end=new DateTimeImmutable($leave['date_to']);$cal=[];while($d<=$end){$key=$d->format('Y-m-d');$month=$d->format('Y-m-01');if(!array_key_exists($month,$cal))$cal[$month]=lt_work_calendar($pdo,$unit,$month);$c=$cal[$month];if($c){$o=json_decode($c['overrides_json'],true);$holiday=isset($o[$key])?(bool)$o[$key]['is_holiday']:(int)$d->format('N')>=6;if(!$holiday)$days++;}else{$s=$pdo->prepare('SELECT is_holiday FROM compensation_work_calendar_days WHERE calendar_date=?');$s->execute([$key]);$h=$s->fetchColumn();if($h!==false&&!(int)$h)$days++;}$d=$d->modify('+1 day');}return $leave['date_from']===$leave['date_to']&&$leave['portion']!=='full'&&$days>0?.5:$days;}
